import React, { useState, useEffect } from 'react';
import Map, { Marker, Popup, NavigationControl } from 'react-map-gl/maplibre';
import 'maplibre-gl/dist/maplibre-gl.css';
import { Plane, Truck, MapPin } from 'lucide-react';

import { getVehicleColor } from './ManageFleetPage';

export default function FleetMap({
  telemetryData,
  vehicleById,
  theme,
  selectedVehicle,
  setSelectedVehicle,
  activeTraces,

  // CAMERA CONTROL PROPS
  pitch,
  bearing,
  setPitch,
  setBearing,
}) {
  const [viewState, setViewState] = useState({
    longitude: -122.4194,
    latitude: 37.7749,
    zoom: 15,
  });

  const [history, setHistory] = useState({});

  useEffect(() => {
    if (selectedVehicle && telemetryData[selectedVehicle]) {
      setViewState((prev) => ({
        ...prev,
        longitude:
          telemetryData[selectedVehicle].longitude,
        latitude:
          telemetryData[selectedVehicle].latitude,
        transitionDuration: 1200,
      }));
    }
  }, [selectedVehicle, telemetryData]);

  useEffect(() => {
    setHistory((prev) => {
      const next = { ...prev };

      Object.values(telemetryData).forEach((pos) => {
        const vId = pos.vehicle_id;

        if (!next[vId]) {
          next[vId] = [];
        }

        const alt = pos.altitude || 0;
        const last = next[vId][next[vId].length - 1];

        if (
          !last ||
          last.lng !== pos.longitude ||
          last.lat !== pos.latitude ||
          last.alt !== alt
        ) {
          next[vId] = [
            ...next[vId],
            {
              lng: pos.longitude,
              lat: pos.latitude,
              alt,
            },
          ];

          if (next[vId].length > 40) {
            next[vId].shift();
          }
        }
      });

      return next;
    });
  }, [telemetryData]);

  const mapStyle = {
    version: 8,

    sources: {
      osm: {
        type: 'raster',

        tiles: [
          'https://a.tile.openstreetmap.org/{z}/{x}/{y}.png',
          'https://b.tile.openstreetmap.org/{z}/{x}/{y}.png',
          'https://c.tile.openstreetmap.org/{z}/{x}/{y}.png',
        ],

        tileSize: 256,

        attribution: '&copy; OpenStreetMap Contributors',
      },
    },

    layers: [
      {
        id: 'osm',
        type: 'raster',
        source: 'osm',
        minzoom: 0,
        maxzoom: 19,
      },
    ],
  };

  const isDark = theme === 'dark';

  const hudBg = isDark
    ? 'var(--bg-glass, rgba(18, 18, 22, 0.95))'
    : 'rgba(255, 255, 255, 0.95)';

  const textColor = isDark ? '#fff' : '#111';
  const subtextColor = isDark ? '#888' : '#555';

  const borderColor = isDark
    ? 'rgba(255,255,255,0.08)'
    : 'rgba(0,0,0,0.1)';

  const btnBg = isDark
    ? 'rgba(255,255,255,0.05)'
    : 'rgba(0,0,0,0.04)';

  return (
    <div
      style={{
        width: '100%',
        height: '100%',
        position: 'relative',
      }}
    >
      <Map
        {...viewState}

        /*
         * IMPORTANT:
         * Pitch and bearing now come from ManageFleetPage.
         * Therefore the HUD controls directly manipulate the
         * actual MapLibre camera.
         */
        pitch={pitch}
        bearing={bearing}

        onMove={(evt) => {
          const nextViewState = evt.viewState;

          // Keep geographic camera state locally.
          setViewState({
            longitude: nextViewState.longitude,
            latitude: nextViewState.latitude,
            zoom: nextViewState.zoom,
          });

          // Keep parent camera state synchronized when
          // the user rotates/tilts the map manually.
          setPitch(nextViewState.pitch);
          setBearing(nextViewState.bearing);
        }}

        mapStyle={mapStyle}

        style={{
          width: '100%',
          height: '100%',
        }}
      >
        <NavigationControl
          position="top-left"
          visualizePitch={true}
        />

        {/* TRACE DOTS */}
        {Object.keys(activeTraces || {}).map((vId) => {
          if (!activeTraces[vId] || !history[vId]) {
            return null;
          }

          const color = getVehicleColor(vId);

          return history[vId].map((point, index) => {
            const opacity =
              0.4 +
              0.6 *
                ((index + 1) / history[vId].length);

            return (
              <Marker
                key={`${vId}-trace-${index}`}
                longitude={point.lng}
                latitude={point.lat}
                anchor="center"
              >
                <div
                  style={{
                    width: '6px',
                    height: '6px',
                    borderRadius: '50%',
                    background: color,
                    opacity,
                    transform: `translateY(-${point.alt}px)`,
                    boxShadow: `0 0 6px ${color}80`,
                    filter: 'brightness(0.75)',
                  }}
                />
              </Marker>
            );
          });
        })}

        {/* LIVE MARKERS */}
        {Object.values(telemetryData).map((pos) => {
          const vehicle = vehicleById[pos.vehicle_id];

          if (!vehicle) {
            return null;
          }

          const isGround = vehicle.category === 'GROUND';

          const altitude = isGround
            ? 0
            : pos.altitude || 50;

          const color = getVehicleColor(pos.vehicle_id);

          return (
            <Marker
              key={pos.vehicle_id}
              longitude={pos.longitude}
              latitude={pos.latitude}
              anchor="bottom"
              onClick={(e) => {
                e.originalEvent.stopPropagation();
                setSelectedVehicle(vehicle.id);
              }}
            >
              <div
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                }}
              >
                <div
                  style={{
                    background: color,
                    color: '#000',
                    borderRadius: '8px',
                    padding: '6px',
                    boxShadow: `0 0 15px ${color}`,
                    transform: `translateY(-${altitude}px)`,
                    transition:
                      'transform 0.3s ease-out',
                  }}
                >
                  {isGround ? (
                    <Truck size={14} />
                  ) : (
                    <Plane size={14} />
                  )}
                </div>

                <div
                  style={{
                    width: '2px',
                    height: `${altitude}px`,
                    background: `linear-gradient(to bottom, ${color}, transparent)`,
                    transition:
                      'height 0.3s ease-out',
                  }}
                />

                <div
                  style={{
                    width: '12px',
                    height: '4px',
                    background: 'rgba(0,0,0,0.6)',
                    borderRadius: '50%',
                    boxShadow:
                      '0 0 4px rgba(0,0,0,0.8)',
                  }}
                />
              </div>
            </Marker>
          );
        })}

        {/* MAP POPUP */}
        {selectedVehicle &&
          telemetryData[selectedVehicle] && (
            <Popup
              longitude={
                telemetryData[selectedVehicle]
                  .longitude
              }
              latitude={
                telemetryData[selectedVehicle]
                  .latitude
              }
              anchor="top"
              onClose={() => setSelectedVehicle(null)}
              closeButton={false}
            >
              <div
                className="map-popup"
                style={{
                  background: isDark
                    ? '#222'
                    : '#fff',
                  color: textColor,
                  border: `1px solid ${borderColor}`,
                  padding: '12px',
                  borderRadius: '12px',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: '8px',
                }}
              >
                <div
                  style={{
                    display: 'flex',
                    justifyContent:
                      'space-between',
                    alignItems: 'center',
                    gap: '20px',
                  }}
                >
                  <b
                    style={{
                      fontSize: '13px',
                    }}
                  >
                    {
                      vehicleById[selectedVehicle]
                        ?.name
                    }
                  </b>

                  <span
                    style={{
                      fontSize: '12px',
                      color: subtextColor,
                      display: 'flex',
                      alignItems: 'center',
                      gap: '4px',
                    }}
                  >
                    <MapPin
                      size={11}
                      strokeWidth={2}
                    />

                    {
                      telemetryData[
                        selectedVehicle
                      ].altitude
                    }
                    m
                  </span>
                </div>
              </div>
            </Popup>
          )}
      </Map>
    </div>
  );
}
